import{_ as a,o,c as d,a0 as c}from"./chunks/framework.CI7OaYtj.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),i={name:"guide/faq.md"};function t(r,e,s,l,n,p){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="hbuilderx-未找到" tabindex="-1">HBuilderX 未找到 <a class="header-anchor" href="#hbuilderx-未找到" aria-label="Permalink to &quot;HBuilderX 未找到&quot;">​</a></h2><p>先启动 HBuilderX，再执行 CLI 命令。macOS 也可检查 <code>/Applications/HBuilderX.app/Contents/MacOS/cli</code>，必要时设置 <code>HBUILDERX_CLI_PATH</code>。</p><h2 id="appid-仍不能运行" tabindex="-1">AppID 仍不能运行 <a class="header-anchor" href="#appid-仍不能运行" aria-label="Permalink to &quot;AppID 仍不能运行&quot;">​</a></h2><p>仓库里的 AppID 仅供演示。请在 DCloud 开发者中心申请自己的 AppID，并同步写入 <code>manifest.config.ts</code> 与生成的 <code>manifest.json</code>。</p><h2 id="修改-pages-json-后被覆盖" tabindex="-1">修改 <code>pages.json</code> 后被覆盖 <a class="header-anchor" href="#修改-pages-json-后被覆盖" aria-label="Permalink to &quot;修改 `pages.json` 后被覆盖&quot;">​</a></h2><p><code>pages.json</code> 是生成物。页面配置写在 <code>definePage</code>，全局配置写在 <code>pages.config.json</code>，TabBar 配置写在 <code>src/tabbar/config.uts</code>。</p><h2 id="uts-编译报错" tabindex="-1">UTS 编译报错 <a class="header-anchor" href="#uts-编译报错" aria-label="Permalink to &quot;UTS 编译报错&quot;">​</a></h2><p>按顺序检查：</p><ul><li>是否使用 <code>interface</code>，应改为 <code>type</code>。</li><li>是否使用 <code>undefined</code>，应改为 <code>null</code>。</li><li>是否使用 <code>===</code> / <code>!==</code>，应改为 <code>==</code> / <code>!=</code>。</li><li>是否出现 <code>.uts</code> / <code>.ts</code> / <code>.js</code> 循环依赖。</li><li>是否裸调用了端专属 API。</li></ul><h2 id="页面入口找不到" tabindex="-1">页面入口找不到 <a class="header-anchor" href="#页面入口找不到" aria-label="Permalink to &quot;页面入口找不到&quot;">​</a></h2><p>检查文件是否位于 <code>src/pages</code> 或 <code>src/sub</code>、是否符合页面命名规则，以及 <code>pages.config.json</code> 中的分包是否仍然存在。</p><h2 id="请求-401-或域名错误" tabindex="-1">请求 401 或域名错误 <a class="header-anchor" href="#请求-401-或域名错误" aria-label="Permalink to &quot;请求 401 或域名错误&quot;">​</a></h2><p>检查 <code>.env.*</code> 中的 <code>VITE_SERVER_BASEURL</code>；小程序还需要在平台后台配置 request 合法域名。</p>',14)])])}const f=a(i,[["render",t]]);export{u as __pageData,f as default};
